    for (const pattern of TOOL_ECHO_PATTERNS) {
      if (pattern.test(trimmed)) { isEcho = true; break; }
    }
    if (!isEcho) { filteredLines.push(line); }
  }
  result = filteredLines.join('\n');
  result = result.replace(/\n{3,}/g, '\n\n');
  return result;
