          this.textEmissionBoundary = Math.max(this.textEmissionBoundary, offset);
          continue;
        } catch { offset = jsonStart + 1; this.textEmissionBoundary = jsonStart; continue; }
      }
      offset = jsonStart + jsonEnd;
      this.textEmissionBoundary = Math.max(this.textEmissionBoundary, offset);
    }
